examples.template:
FlowRow(
    horizontalArrangement = Arrangement.spacedBy(16.dp),
    verticalArrangement = Arrangement.spacedBy(16.dp),
) {
    // The light button sits on a light surface and the dark one on a dark surface, whatever the app theme.
    MonarchTheme(scheme = MonarchScheme.Light, typography = MonarchTheme.typography) {
        Box(modifier = Modifier.background(MonarchTheme.colors.bgSurface).padding(16.dp)) {
            MonarchSignInWithRookButton(onClick = {}, variant = MonarchSignInWithRookButtonVariant.{{variants.0|pascal}}, label = {{label}})
        }
    }
    MonarchTheme(scheme = MonarchScheme.Dark, typography = MonarchTheme.typography) {
        Box(modifier = Modifier.background(MonarchTheme.colors.bgCanvas).padding(16.dp)) {
            MonarchSignInWithRookButton(onClick = {}, variant = MonarchSignInWithRookButtonVariant.{{variants.1|pascal}}, label = {{label}})
        }
    }
    Box(modifier = Modifier.padding(16.dp)) {
        MonarchSignInWithRookButton(onClick = {}, variant = MonarchSignInWithRookButtonVariant.{{variants.2|pascal}}, label = {{label}})
    }
}

